&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Structure analytical approaches and produce clear, decision-ready materials for senior stakeholders.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Own analytical workstreams end-to-end, manage concurrent&amp;nbsp;projects&amp;nbsp;and escalate issues with proposed solutions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Coordinate input from internal teams and work with external stakeholders, including banks, co-investors and partners where needed.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Support portfolio&amp;nbsp;optimisation, growth&amp;nbsp;initiatives&amp;nbsp;and post-acquisition integration where relevant.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Guide junior analysts, review their&amp;nbsp;work&amp;nbsp;and help&amp;nbsp;maintain&amp;nbsp;quality standards across team deliverables.&lt;/span&gt; &amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;What makes you a great&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;candidate&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;?&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
